// Input from the calling workflow: { role, system, prompt, expect_json, required_keys, budget_ms? }
// Builds the chat messages every model gets, and one deadline shared by all model calls,
// so the engine always answers in time even when a provider hangs.
const i = $input.first()?.json ?? {};
const prompt = String(i.prompt ?? '').trim();
if (!prompt) throw new Error('AI Engine received an empty prompt');

const role = String(i.role ?? 'general');
const system = String(i.system ?? '').trim() || 'You are a helpful assistant.';
// routing must be quick (the caller can route by keywords instead); answers get more time
const budget = Number(i.budget_ms) > 0 ? Math.min(Number(i.budget_ms), 55000) : role === 'router' ? 10000 : 28000;

return [{ json: {
  role,
  system,
  prompt,
  expect_json: i.expect_json === true || i.expect_json === 'true',
  required_keys: Array.isArray(i.required_keys) ? i.required_keys.map(String) : [],
  messages: [{ role: 'system', content: system }, { role: 'user', content: prompt }],
  max_tokens: role === 'router' ? 1024 : 2048,
  // models that can reason: think a little for routing, more for customer answers (accuracy, language)
  reasoning_effort: role === 'router' ? 'low' : 'medium',
  budget_ms: budget,
  deadline: Date.now() + budget,
} }];

// Change this sample to try the engine by hand (Execute workflow).
return [{ json: {
  role: 'router',
  system: "You are the request router for an online computer-hardware store. Reply with ONLY this JSON: {\"route\": \"hardware_expert\" | \"calculator\" | \"troubleshooter\"}",
  prompt: "Customer message: มีเมาส์ไร้สายสำหรับเล่นเกม FPS แนะนำไหมครับ",
  expect_json: true,
  required_keys: ['route'],
} }];

// Every model failed (or the input was unusable). Return a normal result so the caller can fall back,
// with each model's error so the cause is easy to find in the execution log.
const STEPS = ["Model 1 Groq GPT-OSS 120B","Check Model 1","Model 2 Groq Qwen 3.8 27B","Check Model 2","Model 3 Typhoon 2.5 Thai","Check Model 3","Model 4 Gemini Flash-Lite","Check Model 4","Model 5 Gemini Flash","Check Model 5","Model 6 OpenRouter Gemma 4 31B","Check Model 6"];
const reasons = [];
for (const step of STEPS) {
  try {
    if (!$(step).isExecuted) continue;
    const e = $(step).all(1).map(i => i.json?.error).find(Boolean);
    if (e) reasons.push(`${step}: ${typeof e === 'string' ? e : e.message ?? JSON.stringify(e)}`.slice(0, 220));
  } catch (x) {}
}
const e = $input.first()?.json?.error;
const last = typeof e === 'string' ? e : (e?.message ?? e?.description ?? '');
const error = (reasons.length ? reasons.join(' | ') : last || 'All AI providers failed').slice(0, 2000);

return [{ json: { ok: false, tier: 0, model: '', text: '', data: null, error } }];

// Accept the answer only if it is usable. Throwing here hands the request to the next model.
const MODEL = "Groq GPT-OSS 120B";
const POSITION = 1;
const cfg = $('Normalize Input').first(0).json;
const r = $input.first()?.json ?? {};
// n8n keeps only the first line of a Code node error, and only the text after its last ":",
// so error messages here are one line and use " - " instead
const fail = msg => { throw new Error(String(msg).replace(/\s+/g, ' ').replace(/\s*:\s*/g, ' - ')); };

// OpenAI-style reply (Groq, Gemini, Typhoon, OpenRouter); Gemini's own format as a fallback
const content = r.choices?.[0]?.message?.content;
let text = typeof content === 'string' ? content
  : Array.isArray(content) ? content.map(p => p?.text ?? '').join('')
  : (r.candidates?.[0]?.content?.parts ?? []).map(p => p?.text ?? '').join('');
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
if (!text) {
  const why = r.error?.message ?? r.choices?.[0]?.finish_reason ?? 'no content';
  fail(`${MODEL} - empty answer (${why})`);
}

let data = null;
if (cfg.expect_json) {
  const cleaned = text.replace(/```(?:json)?/gi, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end <= start) fail(`${MODEL} - answer is not JSON - ${text.slice(0, 200)}`);
  try {
    data = JSON.parse(cleaned.slice(start, end + 1));
  } catch (e) {
    fail(`${MODEL} - invalid JSON (${e.message}) - ${text.slice(0, 200)}`);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) fail(`${MODEL} - JSON is not an object`);
  const missing = cfg.required_keys.filter(k => !(k in data));
  if (missing.length) fail(`${MODEL} - JSON is missing ${missing.join(', ')}`);
}

return [{ json: { ok: true, tier: POSITION, model: MODEL, text, data } }];

